    recordsOverride?: readonly RagMutationRecord[],
    options?: PersistenceLayerOptions
  ): void {
    if (this.syncTimeout) {
      clearTimeout(this.syncTimeout);
    }

    this.syncTimeout = setTimeout(() => {
